package ama.transcript;
import java.util.*;import java.time.*;import java.time.format.*;import java.nio.charset.StandardCharsets;
/** Canonical route/resource-bound history keys; SQL receives typed UTC-local timestamps. */
final class PublicationHistoryCursor {
 private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSSSSS").withResolverStyle(ResolverStyle.STRICT);
 record Key(Long ordinal,LocalDateTime created,String id){}
 static String encode(String route,String meeting,String publication,Map<String,Object> row){String text="v1|"+route+"|"+meeting+(route.equals("finals")?"|"+row.get("meeting_revision"):"|"+publication+(route.equals("submissions")?"|"+row.get("submission_no"):"|"+TIME.format(time(row.get("created_at")))+"|"+row.get("id")));return Base64.getUrlEncoder().withoutPadding().encodeToString(text.getBytes(StandardCharsets.US_ASCII));}
 static Key decode(String route,String meeting,String publication,String cursor){if(cursor==null)return null;try{if(!Set.of("finals","submissions","attempts").contains(route)||cursor.length()>256||!cursor.matches("[A-Za-z0-9_-]+"))throw new IllegalArgumentException();byte[] bytes=Base64.getUrlDecoder().decode(cursor);if(!Base64.getUrlEncoder().withoutPadding().encodeToString(bytes).equals(cursor))throw new IllegalArgumentException();for(byte b:bytes)if(b<32||b>126)throw new IllegalArgumentException();String[] f=new String(bytes,StandardCharsets.US_ASCII).split("\\|",-1);int size=route.equals("finals")?4:route.equals("submissions")?5:6;if(f.length!=size||!f[0].equals("v1")||!f[1].equals(route)||!f[2].equals(meeting)||!route.equals("finals")&&!f[3].equals(publication))throw new IllegalArgumentException();if(!route.equals("attempts")){String n=f[size-1];if(!n.matches("[1-9][0-9]{0,18}"))throw new IllegalArgumentException();long value=Long.parseLong(n);if(value>=Long.MAX_VALUE)throw new IllegalArgumentException();return new Key(value,null,null);}LocalDateTime at=LocalDateTime.parse(f[4],TIME);if(!TIME.format(at).equals(f[4])||!UUID.fromString(f[5]).toString().equals(f[5]))throw new IllegalArgumentException();return new Key(null,at,f[5]);}catch(RuntimeException invalid){throw new IllegalArgumentException("Invalid history cursor");}}
 static LocalDateTime time(Object value){if(value instanceof java.sql.Timestamp t)return t.toLocalDateTime();if(value instanceof LocalDateTime t)return t;return LocalDateTime.parse(value.toString());}
}
